/**
 * Stamp `MCPJAM_WEB_DEPLOYED_AT` with the time this release build ran.
 *
 * The MCPJam row of the host catalog describes THIS app, so its facts are only
 * as fresh as the build that shipped them — `resolveVerifiedAt` prefers this
 * stamp over the catalog's hand-stamped date for `mcpjam` alone. Every surface
 * that ships a client bundle to users has to write it, or that surface falls
 * back to a catalog date that ages independently of the app:
 *
 *   - deploy-webapp.yml    → app.mcpjam.com (Railway)
 *   - release.yml          → the `@mcpjam/inspector` tarball behind `npx`
 *   - mac-release.yml      → the macOS desktop app
 *   - windows-release.yml  → the Windows desktop app
 *
 * Writing a tracked input also invalidates Docker's client-build layer when the
 * same SHA is deliberately redeployed.
 *
 * The file is committed as `null` — local and non-production builds keep the
 * catalog date — so this only ever runs in CI, on a throwaway checkout, and is
 * never committed back.
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// Resolved from this script, not `process.cwd()`, so a workflow step with a
// different working directory still writes the one file the client imports.
const target = fileURLToPath(
  new URL(
    "../../mcpjam-inspector/client/src/generated/mcpjam-web-deployed-at.ts",
    import.meta.url
  )
);

const stampedAt = Date.now();

writeFileSync(
  target,
  `// Generated by .github/scripts/stamp-mcpjam-build-time.mjs. Do not edit.\nexport const MCPJAM_WEB_DEPLOYED_AT: number | null = ${stampedAt};\n`
);

console.log(
  `Stamped MCPJAM_WEB_DEPLOYED_AT=${stampedAt} (${new Date(
    stampedAt
  ).toISOString()})`
);
